corrected_code:
const amqp = require('amqplib');

async function startBackupPurgeWorker() {
  const conn = await amqp.connect(process.env.AMQP_BROKER_URL);
  const ch = await conn.createChannel();
  await ch.assertQueue('cloud.snapshot.retention_purge');

  ch.consume('cloud.snapshot.retention_purge', async (msg) => {
    const payload = JSON.parse(msg.content.toString());
    const { snapshotId, requesterUserId } = payload;

    const snapshot = await SnapshotModel.findOne({
      _id: snapshotId,
      ownerUserId: requesterUserId
    });
    if (!snapshot) {
      console.error(`Purge authorization failed for snapshot ${snapshotId} requested by ${requesterUserId}`);
      ch.ack(msg);
      return;
    }

    await ec2Client.send(new DeleteSnapshotCommand({ SnapshotId: snapshot.awsSnapshotId }));
    await snapshot.deleteOne();
    ch.ack(msg);
  });
}
